"""Offline WP9 gate candidate. Pure decision function; never dispatches work.
Production requires trusted DB receipt loader, distinct review and fenced integration.
Caller-provided objects alone are NOT authoritative acceptance evidence.
"""
import hashlib,json,re
SCOPE="12eb5e29edcd7f5d2fd5a98b9f4346983a28f9a93d9b858a33279a1b11c725f4"
def digest(value):
    return hashlib.sha256(json.dumps(value,sort_keys=True,separators=(",",":"),allow_nan=False).encode()).hexdigest()
def sha(value):
    return isinstance(value,str) and re.fullmatch("[0-9a-f]{64}",value) is not None
def decide(snapshot):
    if not isinstance(snapshot,dict): return {"state":"HOLD","missing":["SNAPSHOT_OBJECT"]}
    missing=[]
    control=snapshot.get("control",{})
    if not isinstance(control,dict):control={}
    for key in ["owner_current","fence_current","stop_current","admission_current","resources_current","implementation_reviewed","receipt_loader_verified"]:
        if control.get(key) is not True: missing.append("CONTROL_"+key.upper())
    if snapshot.get("authorization")!="GRANTED" or snapshot.get("research_scope_sha256")!=SCOPE:missing.append("SCOPED_AUTHORIZATION")
    pins=snapshot.get("pins",{})
    if not isinstance(pins,dict):pins={}
    for key in ["input_manifest_sha256","protocol_sha256","research_scope_sha256"]:
        if not sha(pins.get(key)):missing.append("PIN_"+key.upper())
    if pins.get("research_scope_sha256")!=SCOPE:missing.append("RESEARCH_SCOPE_PIN")
    for name,required in {
       "data":["consumer_readback","coverage_measured","omissions_frozen","session_action_semantics","lookback_and_outcomes_supported","asof_qualified","mandatory_features_present"],
       "protocol":["frozen_before_evaluation","exposure_audit_complete","timing_defined","folds_purge_embargo_defined","search_bounds_frozen","costs_and_support_frozen","all_trials_preserved","report_schema_defined"]
    }.items():
        gate=snapshot.get(name,{})
        if not isinstance(gate,dict):gate={}
        if gate.get("result")!="PASS":missing.append(name.upper()+"_PASS_RECEIPT")
        if gate.get("pins")!=pins:missing.append(name.upper()+"_CURRENT_PINS")
        if not sha(gate.get("receipt_sha256")):missing.append(name.upper()+"_RECEIPT_HASH")
        if not gate.get("producer_execution") or not gate.get("reviewer_execution") or gate.get("producer_execution")==gate.get("reviewer_execution"):missing.append(name.upper()+"_DISTINCT_REVIEW")
        for key in required:
            if gate.get(key) is not True:missing.append(name.upper()+"_"+key.upper())
    if missing:return {"state":"HOLD","missing":sorted(set(missing))}
    return {"state":"ELIGIBLE_FOR_FENCED_DISPATCH","dispatch_key":digest({"scope":SCOPE,"pins":pins}),"research_executed":False}

